class Solution {
public:
    bool isValid(string s) {
        const vector<string> pairs = {"()", "[]", "{}"};
        bool changed = true;
        while (changed) {
            changed = false;
            for (const string& p : pairs) {
                size_t pos;
                while ((pos = s.find(p)) != string::npos) {
                    s.erase(pos, 2);
                    changed = true;
                }
            }
        }
        return s.empty();
    }
};

