        vector<char> stack;
        for (char c : s) {
            if (mapping.count(c)) {
                if (stack.empty() || stack.back() != mapping[c]) return false;
                stack.pop_back();
            } else {
                stack.push_back(c);
            }
        }
        return stack.empty();
    }
};

